const { mkdtempSync, mkdirSync, writeFileSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { execFileSync } = await import("child_process");
const tempRoot = mkdtempSync(join(tmpdir(), "koala-parallel-fixture-"));
mkdirSync(join(tempRoot, "docs", "story", "actives"), { recursive: true });
mkdirSync(join(tempRoot, "docs", "requirements"), { recursive: true });
writeFileSync(join(tempRoot, "koala.config.json"), JSON.stringify({
  scanRoot: "packages/main",
  rootDir: "src",
  outDir: "packages/main/dist",
  testsDir: "packages/main/tests",
  fixturesDir: "packages/main/tests/fixtures",
  storyDir: "docs/story/actives",
  requirementsDir: "docs/requirements",
  storyPrefix: "B"
}, null, 2));
const cli = $root + "/packages/main/dist/cli.js";
const run = (command, payload = {}) => execFileSync("node", [cli, "--root", tempRoot, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractStoryId = (text) => {
  const match = text.match(/B-[a-f0-9]+/);
  if (!match) throw new Error("failed to parse story id from " + text);
  return match[0];
};
$ctx.parallelTmp = tempRoot;
$ctx.parallelCli = cli;
$ctx.primaryId = extractStoryId(run("story_create", {
  name: "parallel-primary",
  title: "Primary lane story",
  description: "Mainline story for fixture verification.",
  type: "feature",
  priority: "high",
  phase: "DEV",
  lane: "mainline",
  parallelSafe: "no",
  sharedHotspots: ["packages/main/src/handlers/session.ts"]
}));
$ctx.candidateId = extractStoryId(run("story_create", {
  name: "parallel-candidate",
  title: "Supporting plan-only story",
  description: "Supporting story that should stay in PLAN.",
  type: "chore",
  priority: "medium",
  phase: "PLAN",
  lane: "supporting",
  parallelSafe: "plan_only",
  sharedHotspots: ["packages/main/src/handlers/worktree.ts"]
}));
$ctx.conflictId = extractStoryId(run("story_create", {
  name: "parallel-conflict",
  title: "Conflicting DEV story",
  description: "Supporting story that collides with the primary hotspot.",
  type: "feature",
  priority: "medium",
  phase: "DEV",
  lane: "supporting",
  parallelSafe: "yes",
  sharedHotspots: ["packages/main/src/handlers/session.ts"]
}));
$ctx.reviewId = extractStoryId(run("story_create", {
  name: "parallel-review-target",
  title: "Review target for parallel policy",
  description: "Validate story_review parallel policy advisories.",
  type: "feature",
  priority: "high",
  phase: "PLAN",
  depends: [$ctx.primaryId],
  lane: "supporting",
  parallelSafe: "yes",
  sharedHotspots: ["packages/main/src/handlers/session.ts"],
  checklist: [{
    title: "Plan the multi-session execution policy",
    context: "Need advisory-only guardrails before any hard gates.",
    testIntent: {
      happy: [{ desc: "primary lane and candidates are visible", type: "cli_blackbox" }],
      edge: [{ desc: "depends + parallelSafe=yes warns instead of hard failing", type: "cli_blackbox" }],
      adversarial: [{ desc: "shared hotspot overlap is surfaced as a conflict warning", type: "cli_blackbox" }]
    }
  }]
}));
run("understanding_set", {
  storyId: $ctx.reviewId,
  task: "Verify story_review parallel policy advisory behavior",
  outcome: ">>> koala session_brief\n## Primary lane\n  B-xxxx DEV Primary lane story [mainline/no]\n## Parallel candidates\n  B-yyyy PLAN [supporting/plan_only] keep this in PLAN only\n## Conflict warnings\n  - B-zzzz: shares hotspots with B-xxxx: packages/main/src/handlers/session.ts",
  facts: ["parallelSafe=yes should stay advisory even with depends"],
  constraints: ["first version is advisory-only"],
  unknowns: [],
  touchpoints: ["packages/main/src/handlers/story-review.ts"]
});
run("decision_set", {
  storyId: $ctx.reviewId,
  principles: ["Prefer advisory over hard gate", "Expose conflicts early", "Keep the model understandable"],
  drivers: ["avoid harming mainline tasks", "support multi-session planning"],
  options: [
    { name: "A: advisory review + brief hints", pros: ["low friction"], cons: ["operators must read warnings"] },
    { name: "B: hard gate on every conflict", pros: ["strict safety"], cons: ["too heavy for first rollout"] }
  ],
  chosen: "A: advisory review + brief hints",
  rationale: "The first rollout should surface conflicts without blocking legitimate planning work.",
  preMortem: [
    { scenario: "Hints are too noisy", trigger: "Every story gets multiple warnings", consequence: "Operators ignore them", mitigation: "Keep checks focused on lane/safety/hotspot mismatches" },
    { scenario: "Conflicts stay invisible", trigger: "Hotspots are omitted", consequence: "Parallel DEV collides later", mitigation: "Add a missing_hotspots advisory" },
    { scenario: "Dependencies are ignored", trigger: "parallelSafe=yes on downstream story", consequence: "A dependent story races into DEV", mitigation: "Flag depends + yes as advisory" }
  ]
});
$ctx.missingMetaId = extractStoryId(run("story_create", {
  name: "parallel-missing-metadata",
  title: "Missing policy metadata story",
  description: "Validate missing lane/safety/hotspot advisories.",
  type: "chore",
  priority: "medium",
  phase: "PLAN",
  checklist: [{
    title: "Document the rollout shape",
    context: "Need enough structure for a lightweight review.",
    testIntent: {
      happy: [{ desc: "review still runs without blocking", type: "cli_blackbox" }],
      edge: [{ desc: "missing metadata is surfaced clearly", type: "cli_blackbox" }],
      adversarial: [{ desc: "operators do not need to guess what to fill next", type: "cli_blackbox" }]
    }
  }]
}));
run("understanding_set", {
  storyId: $ctx.missingMetaId,
  task: "Verify missing parallel metadata advisories",
  outcome: "> koala story_review\nparallel_policy_missing_lane\nparallel_policy_missing_safety\nparallel_policy_missing_hotspots",
  facts: ["metadata is optional but should be nudged"],
  constraints: ["must remain advisory"],
  unknowns: [],
  touchpoints: ["packages/main/src/handlers/story-review.ts"]
});
run("decision_set", {
  storyId: $ctx.missingMetaId,
  principles: ["Keep the policy light", "Prefer explicit metadata over guesses", "Do not block planning"],
  drivers: ["clarity", "low friction"],
  options: [
    { name: "A: advisory nudges", pros: ["easy to adopt"], cons: ["relies on operator follow-through"] },
    { name: "B: hard gate", pros: ["strict completeness"], cons: ["too disruptive"] }
  ],
  chosen: "A: advisory nudges",
  rationale: "Missing metadata should be visible, but teams still need room to keep planning moving."
});
return { createdAll: Boolean($ctx.primaryId && $ctx.candidateId && $ctx.conflictId && $ctx.reviewId && $ctx.missingMetaId) };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const brief = run("session_brief");
return { missingMetaVisible: brief.includes($ctx.missingMetaId), defaultPolicyVisible: brief.includes('[supporting/plan_only]') };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const review = extractJsonObject(run("story_review", { storyId: $ctx.reviewId }));
return { dependsConflict: review.issues.some((issue) => issue.type === "parallel_policy_depends_conflict"), hotspotConflict: review.issues.some((issue) => issue.type === "parallel_policy_conflict") };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const brief = run("session_brief");
return { hasPrimarySection: brief.includes("## Primary lane"), primaryStoryShown: brief.includes($ctx.primaryId), primaryPolicyShown: brief.includes('[mainline/no]') };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const brief = run("session_brief");
return { hasCandidatesSection: brief.includes("## Parallel candidates"), candidateShown: brief.includes($ctx.candidateId), planOnlyHint: brief.includes("keep this in PLAN only") || brief.includes("plan_only") };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const brief = run("session_brief");
const candidateSection = brief.includes("## Conflict warnings") ? brief.split("## Conflict warnings")[0] : brief;
const candidateLine = $ctx.conflictId + " DEV [supporting/yes] ready for parallel DEV";
return { hasConflictWarning: brief.includes($ctx.conflictId), notRecommendedAsCandidate: !candidateSection.includes(candidateLine) };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const review = extractJsonObject(run("story_review", { storyId: $ctx.reviewId }));
return { issueVisible: review.issues.some((issue) => issue.type === "parallel_policy_conflict"), advisoryOnly: (review.summary?.blockerCount ?? 0) === 0 };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const review = extractJsonObject(run("story_review", { storyId: $ctx.missingMetaId }));
const types = new Set(review.issues.map((issue) => issue.type));
return { lane: types.has("parallel_policy_missing_lane"), safety: types.has("parallel_policy_missing_safety"), hotspots: types.has("parallel_policy_missing_hotspots"), blockerCountZero: (review.summary?.blockerCount ?? 0) === 0 };

const { execFileSync } = await import("child_process");
const run = (command, payload = {}) => execFileSync("node", [$ctx.parallelCli, "--root", $ctx.parallelTmp, command, JSON.stringify(payload)], {
  cwd: $root,
  encoding: "utf8",
  stdio: ["pipe", "pipe", "pipe"],
});
const extractJsonObject = (text) => JSON.parse(text.slice(text.indexOf("{")));
const review = extractJsonObject(run("story_review", { storyId: $ctx.reviewId }));
return { hotspotPathNamed: review.issues.some((issue) => issue.message.includes("packages/main/src/handlers/session.ts")) };

const { execFileSync } = await import("child_process");
const out = execFileSync("node", ["scripts/verify-parallel-execution-policy.mjs"], { cwd: $root, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] });
return { verified: out.includes("parallel execution policy verified") };

const { readFileSync } = await import("fs");
const text = readFileSync($root + "/package.json", "utf8");
return { hasScript: text.includes('"test:parallel-policy"') };

const { readFileSync, rmSync, existsSync } = await import("fs");
const script = readFileSync($root + "/scripts/verify-parallel-execution-policy.mjs", "utf8");
const tempRoot = $ctx.parallelTmp;
rmSync(tempRoot, { recursive: true, force: true });
return { checksBrief: script.includes('## Primary lane') && script.includes('## Parallel candidates'), checksReview: script.includes('parallel_policy_conflict'), cleaned: !existsSync(tempRoot) };
